## ---- 01: The Kalman Filter for DNS  (qmd line 74) -----------------------------------

library(KFAS)

# Nelson-Siegel loading matrix on the maturity grid (months), so
# lambda is the per-month 0.0609 (Chapter 2). A grid in years would
# take 0.7308 instead.
mats   <- c(3, 6, 12, 24, 36, 60, 84, 120, 240, 360)
lambda <- 0.0609
L2 <- (1 - exp(-lambda * mats)) / (lambda * mats)
L3 <- L2 - exp(-lambda * mats)
Lambda <- cbind(1, L2, L3)

# Transition inputs from the two-step fit (Chapter 2); Phi is held
# fixed here, while Q and H are estimated by maximum likelihood
Phi    <- diag(c(0.99, 0.94, 0.90))
mu     <- c(0.045, -0.01, 0.005)
P_init <- diag(0.1, 3)

# y_obs: T x K matrix of observed yields (simulated here for
# illustration; in practice use the panel from Chapter 1)
set.seed(42)
n_obs <- 200
f <- matrix(0, n_obs, 3)
f[1, ] <- mu
for (t in 2:n_obs) {
  f[t, ] <- mu + (f[t - 1, ] - mu) %*% Phi +
    rnorm(3, 0, c(3, 4, 5) * 1e-4)
}
y_obs <- f %*% t(Lambda) +
  matrix(rnorm(n_obs * length(mats), 0, 5e-4), n_obs)

# Define the DNS state-space model; NA variances are estimated
mod <- SSModel(y_obs ~ -1 + SSMcustom(Z = Lambda,
                                      T = Phi,
                                      R = diag(3),
                                      Q = diag(NA_real_, 3),
                                      a1 = mu,
                                      P1 = P_init),
               H = diag(NA_real_, length(mats)))

# Fit by maximum likelihood over the Q and H variances (a custom
# updatefn extends the search to Phi for full one-step estimation)
fit <- fitSSM(mod, inits = rep(log(1e-6), 13), method = "BFGS")

# Extract smoothed factor estimates
filt <- KFS(fit$model)
beta_smoothed <- filt$alphahat


