## ---- 03: A Typical Calibration Workflow  (qmd line 288) ------------------------------

library(dnsr)

# 1. Load Treasury data from FRED and reduce to a monthly panel
rates_df <- get_treasury_yield_combined(start_date = "2000-01-01")
monthly  <- rates_df[order(rates_df$Date), ]
monthly  <- monthly[!duplicated(format(monthly$Date, "%Y-%m"),
                                fromLast = TRUE), ]  # month-end rows

# 2. Extract factors via date-by-date fits with fixed lambda.
# The panel's maturity columns are in years, so lambda is per year:
# Diebold-Li's 0.0609 per month is 0.0609 * 12 (Chapter 2).
dns_fit <- fit_dns_model(monthly, n_days = nrow(monthly),
                         initial_lambda = 0.7308,
                         lambda_constraint = "fixed")
factors_ts <- dns_fit$parameters  # Date, beta1, beta2, beta3, ...

# 3. Fit OU dynamics (monthly steps: dt = 1/12)
fit <- estimate_dns_dynamics(factors_ts, dt = 1/12)
# fit returns per-factor kappa, theta, sigma plus the shock correlation

# 4. Save calibrated parameters for downstream simulation
saveRDS(fit, "dns_calibrated_params.rds")


## ---- 04: Date-by-Date Fit and Factor Time Series  (qmd line 339) ---------------------

library(dnsr)
library(dplyr); library(purrr); library(tibble)
library(ggplot2)

# Build factor time series via dnsr::fit_dns_model. n_days defaults to
# 60, which leaves too few month-ends for the dynamics step below, so
# fit a multi-year window (Chapter 5 uses the same 1250-day window).
panel <- get_treasury_yield_combined(start_date = "2010-01-01")
fit_panel <- fit_dns_model(panel, n_days = 1250, initial_lambda = 0.7308,
                           lambda_constraint = "fixed")
# fit_panel$parameters is a data.frame: Date, beta1, beta2, beta3,
# lambda, rmse, plus day-over-day factor changes
factor_ts <- fit_panel$parameters

head(factor_ts)
ggplot(factor_ts, aes(Date, beta1)) +
  geom_line() +
  labs(x = NULL, y = "Level") +
  theme_minimal()


## ---- 05: Estimating OU Dynamics  (qmd line 363) --------------------------------------

# Subsample month-end factors: daily refits re-measure the same
# underlying factors with noise, which biases mean-reversion speeds
# upward, so dynamics are estimated at the monthly step
factor_monthly <- factor_ts[order(factor_ts$Date), ]
me <- !duplicated(format(factor_monthly$Date, "%Y-%m"),
                  fromLast = TRUE)
factor_monthly <- factor_monthly[me, ]

# Helper: per-factor OU calibration via discrete AR(1) (didactic)
fit_univ_ou <- function(x, dt = 1/12) {
  ar1 <- ar(x, order.max = 1, method = "mle", aic = FALSE)
  phi <- ar1$ar
  kappa <- -log(phi) / dt
  list(kappa = kappa, theta = ar1$x.mean,
       sigma = sqrt(ar1$var.pred * 2 * kappa / (1 - phi^2)),
       half_life_years = log(2) / kappa)
}

ou_fits <- lapply(factor_monthly[, c("beta1","beta2","beta3")],
                  fit_univ_ou)
ou_fits$beta1


## ---- 06: Multivariate Estimation via `dnsr::estimate_dns_dynamics`  (qmd line 389) ---

# Use dnsr's bundled estimator for the full 3x3 system, on the same
# month-end subsample (factor changes recomputed at the monthly step)
for (f in c("beta1", "beta2", "beta3")) {
  factor_monthly[[paste0(f, "_change")]] <-
    c(NA, diff(factor_monthly[[f]]))
}
dynamics <- estimate_dns_dynamics(factor_monthly, dt = 1/12)
str(dynamics, max.level = 1)   # per-factor kappa/theta/sigma + correlation


## ---- 07: Kalman Filter via KFAS  (qmd line 402) --------------------------------------

library(KFAS)

# Loadings at the panel's own maturities (colnames are years), so
# lambda is per year
mats <- as.numeric(colnames(panel)[-1])
lam  <- 0.7308
L2   <- (1 - exp(-lam * mats)) / (lam * mats)
Lambda <- cbind(1, L2, L2 - exp(-lam * mats))

mod <- SSModel(
  as.matrix(panel[, -1]) ~ -1 +
    SSMcustom(Z = Lambda,
              T = diag(c(0.99, 0.95, 0.90)),
              R = diag(3),
              Q = diag(c(1e-5, 5e-5, 2e-4))),
  H = diag(rep(1e-6, length(mats)))
)

filt <- KFS(mod)
# filt$alphahat: smoothed factor estimates


## ---- 08: Forecasting  (qmd line 427) -------------------------------------------------

# Simple VAR(1) forecast on the month-end factors: 12 steps ahead
# at the monthly frequency is a one-year horizon
library(vars)
v <- VAR(factor_monthly[, c("beta1","beta2","beta3")], p = 1)
fc <- predict(v, n.ahead = 12)
sapply(fc$fcst, function(x) x[, "fcst"])


